        /**
         * Landed commit id.
         */commit: String, 
        /**
         * Number of commits landed.
         */commits: UInt64, 
        /**
         * Branch that moved.
         */targetBranch: String, 
        /**
         * The target branch is checked out on the machine.
         */checkedOut: Bool
    )
    /**
     * A rebase conflict; the worktree is unchanged.
     */
    case conflict(
        /**
         * Stable code (`land_conflict`).
         */code: String, 
        /**
         * Paths in conflict.
         */conflictingPaths: [String]
    )





}

