/**
 * Session lifecycle events (core `SessionEvent`).
 */

public enum SessionEventRecord: Equatable, Hashable {
    
    /**
     * No usable session exists.
     */
    case signedOut
    /**
     * A stored session was restored for the first paint, not yet admitted.
     */
    case restored(
        /**
         * Cached display name, when known.
         */displayName: String?
    )
    /**
     * The server admitted the session.
     */
    case admitted(
        /**
         * Account username.
         */username: String, 
        /**
         * Absolute expiry in unix milliseconds, for paired sessions.
         */expiresAt: UInt64?
    )
    /**
     * The session expired.
     */
    case expired
    /**
     * The server kept the session but asks to verify this device or to
     * sign in again before it admits it; credentials stay stored.
     */
    case verificationRequired(
        /**
         * What the server asks for.
         */verification: SessionVerificationRecord
    )
    /**
     * Access was denied.
     */
    case accessDenied(
        /**
         * Why.
         */denial: AccessDenialRecord
    )





}

