/**
 * Progress of a send or live reply (core `StreamEvent`).
 */

public enum StreamEventRecord: Equatable, Hashable {
    
    /**
     * The assistant asks permission to use the listed items.
     */
    case consent(
        /**
         * Consent request id.
         */requestId: String, 
        /**
         * Items the assistant wants to use.
         */items: [EmbedRefRecord]
    )
    /**
     * Sending began.
     */
    case started(
        /**
         * Chat id.
         */chatId: String, 
        /**
         * User message id.
         */messageId: String, 
        /**
         * A reply will follow.
         */expectsReply: Bool
    )
    /**
     * The server task answering the turn is known (before any reply text);
     * pass `task_id` to `stopReply`.
     */
    case taskAssigned(
        /**
         * Chat id.
         */chatId: String, 
        /**
         * User message id of the turn.
         */messageId: String, 
        /**
         * Server task id.
         */taskId: String
    )
    /**
     * Dispatch may have committed; never resend automatically.
     */
    case submitted(
        /**
         * Chat id.
         */chatId: String, 
        /**
         * User message id.
         */messageId: String
    )
    /**
     * The server acknowledged persistence of the user message.
     */
    case admitted(
        /**
         * Chat id.
         */chatId: String, 
        /**
         * User message id.
         */messageId: String
    )
    /**
     * Reply text so far.
     */
    case content(
        /**
         * Visible reply text.
         */content: String, 
        /**
         * Reasoning text.
         */thinking: String, 
        /**
         * Mate producing the reply.
         */mate: String
    )
    /**
     * The reply finished.
     */
    case completed(
        /**
         * Chat id.
         */chatId: String, 
        /**
         * Reply message id.
         */messageId: String, 
        /**
         * Final reply text.
         */content: String
    )
    /**
     * Human-readable progress note.
     */
    case status(
        /**
         * Note text.
         */message: String
    )





}

#if compiler(>=6)
extension StreamEventRecord: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeStreamEventRecord: FfiConverterRustBuffer {
    typealias SwiftType = StreamEventRecord

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> StreamEventRecord {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .consent(requestId: try FfiConverterString.read(from: &buf), items: try FfiConverterSequenceTypeEmbedRefRecord.read(from: &buf)
        )
        
        case 2: return .started(chatId: try FfiConverterString.read(from: &buf), messageId: try FfiConverterString.read(from: &buf), expectsReply: try FfiConverterBool.read(from: &buf)
        )
        
        case 3: return .taskAssigned(chatId: try FfiConverterString.read(from: &buf), messageId: try FfiConverterString.read(from: &buf), taskId: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .submitted(chatId: try FfiConverterString.read(from: &buf), messageId: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .admitted(chatId: try FfiConverterString.read(from: &buf), messageId: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .content(content: try FfiConverterString.read(from: &buf), thinking: try FfiConverterString.read(from: &buf), mate: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .completed(chatId: try FfiConverterString.read(from: &buf), messageId: try FfiConverterString.read(from: &buf), content: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .status(message: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: StreamEventRecord, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .consent(requestId,items):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(requestId, into: &buf)
            FfiConverterSequenceTypeEmbedRefRecord.write(items, into: &buf)
            
        
        case let .started(chatId,messageId,expectsReply):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterString.write(messageId, into: &buf)
            FfiConverterBool.write(expectsReply, into: &buf)
            
        
        case let .taskAssigned(chatId,messageId,taskId):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterString.write(messageId, into: &buf)
            FfiConverterString.write(taskId, into: &buf)
            
        
        case let .submitted(chatId,messageId):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterString.write(messageId, into: &buf)
            
        
        case let .admitted(chatId,messageId):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterString.write(messageId, into: &buf)
            
        
        case let .content(content,thinking,mate):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(content, into: &buf)
            FfiConverterString.write(thinking, into: &buf)
            FfiConverterString.write(mate, into: &buf)
            
        
        case let .completed(chatId,messageId,content):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterString.write(messageId, into: &buf)
            FfiConverterString.write(content, into: &buf)
            
        
        case let .status(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


