/**
 * Payload-free failure class (core `ViewErrorKind`).
 */

public enum ViewErrorKindRecord: Equatable, Hashable {
    
    /**
     * Caller supplied an invalid request.
     */
    case invalid
    /**
     * Cryptographic operation failed.
     */
    case crypto
    /**
     * Credentials were refused.
     */
    case authentication
    /**
     * A second factor is required.
     */
    case twoFactorRequired
    /**
     * Signup is required.
     */
    case signupRequired
    /**
     * A capability is unavailable.
     */
    case unavailable(
        /**
         * Stable code of the refusal.
         */code: String
    )
    /**
     * Local data is locked.
     */
    case locked
    /**
     * No network.
     */
    case offline
    /**
     * Access is forbidden.
     */
    case forbidden
    /**
     * The session expired.
     */
    case expired
    /**
     * The server asks to verify this device or to sign in again.
     */
    case verificationRequired
    /**
     * The operation was cancelled.
     */
    case cancelled
    /**
     * Local I/O failed.
     */
    case io
    /**
     * The server answered outside the protocol.
     */
    case protocolError
    /**
     * A concurrent change conflicted.
     */
    case conflict





}

