/**
 * What the core tells the Swift shell (core `ViewEvent`). Request ids are
 * the core's `RequestId` values.
 */

public enum ViewEventRecord: Equatable, Hashable {
    
    /**
     * Session lifecycle change.
     */
    case session(
        /**
         * The change.
         */event: SessionEventRecord
    )
    /**
     * Initial sync advanced.
     */
    case syncProgress(
        /**
         * Phase just reached.
         */phase: SyncPhaseRecord, 
        /**
         * Items received so far.
         */received: UInt64
    )
    /**
     * The chat list changed.
     */
    case chatList(
        /**
         * Rows in display order.
         */rows: [ChatListRowRecord], 
        /**
         * How far the list can be trusted.
         */completeness: ListCompletenessRecord, 
        /**
         * Chats the account has in this scope as the server last reported it;
         * `None` until reported.
         */totalCount: UInt64?
    )
    /**
     * A chat window is ready or changed.
     */
    case chatWindow(
        /**
         * Request that asked for it.
         */request: UInt64, 
        /**
         * The window.
         */window: ChatWindowViewRecord
    )
    /**
     * A chat is gone or unreadable.
     */
    case chatUnavailable(
        /**
         * Affected chat.
         */chatId: String
    )
    /**
     * Opening a chat failed.
     */
    case chatOpenFailed(
        /**
         * Request that failed.
         */request: UInt64, 
        /**
         * Chat that failed to open.
         */chatId: String, 
        /**
         * Failure class.
         */error: ViewErrorKindRecord
    )
    /**
     * One message of the open window changed while its reply streams (the
     * whole message as it is now; an id not shown yet is appended). Sent
     * instead of a full `ChatWindow` per reply-text update, after the
     * `Stream` event that caused it.
     */
    case messageUpdated(
        /**
         * Request of the window (the send's request).
         */request: UInt64, 
        /**
         * Chat of the window.
         */chatId: String, 
        /**
         * The changed message.
         */message: MessageViewRecord
    )
    /**
     * Progress of a send.
     */
    case stream(
        /**
         * Request that started the send.
         */request: UInt64, 
        /**
         * Chat the stream belongs to.
         */chatId: String, 
        /**
         * The progress item.
         */event: StreamEventRecord
    )
    /**
     * Human-readable progress note.
     */
    case status(
        /**
         * Note text.
         */message: String
    )
    /**
     * A request failed.
     */
    case failed(
        /**
         * Failure class.
         */error: ViewErrorKindRecord
    )
    /**
     * The current unit of work finished.
     */
    case done
    /**
     * The saved draft of `chat_id` changed on another device (saved or
     * cleared) and a refresh applied it: an open composer of that chat
     * shows `draft` (`nil`: cleared or chat gone). This core's own saves
     * and clears are never echoed (core `DraftChanged`).
     */
    case draftChanged(
        /**
         * Chat whose draft changed.
         */chatId: String, 
        /**
         * The draft as it is now.
         */draft: DraftViewRecord?
    )
    /**
     * An inbound socket frame of a shell feature the core does not own yet
     * (core `UnownedSocketFrame`; temporary strangler seam).
     */
    case unownedSocketFrame(
        /**
         * The frame's `type` name.
         */eventType: String, 
        /**
         * The frame's payload as JSON text.
         */payloadJson: String
    )
    /**
     * `count` unowned frames were dropped here; re-read their state (core
     * `UnownedSocketFramesDropped`).
     */
    case unownedSocketFramesDropped(
        /**
         * Frames lost at this position.
         */count: UInt64
    )





}

#if compiler(>=6)
extension ViewEventRecord: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeViewEventRecord: FfiConverterRustBuffer {
    typealias SwiftType = ViewEventRecord

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ViewEventRecord {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .session(event: try FfiConverterTypeSessionEventRecord.read(from: &buf)
        )
        
        case 2: return .syncProgress(phase: try FfiConverterTypeSyncPhaseRecord.read(from: &buf), received: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 3: return .chatList(rows: try FfiConverterSequenceTypeChatListRowRecord.read(from: &buf), completeness: try FfiConverterTypeListCompletenessRecord.read(from: &buf), totalCount: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        case 4: return .chatWindow(request: try FfiConverterUInt64.read(from: &buf), window: try FfiConverterTypeChatWindowViewRecord.read(from: &buf)
        )
        
        case 5: return .chatUnavailable(chatId: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .chatOpenFailed(request: try FfiConverterUInt64.read(from: &buf), chatId: try FfiConverterString.read(from: &buf), error: try FfiConverterTypeViewErrorKindRecord.read(from: &buf)
        )
        
        case 7: return .messageUpdated(request: try FfiConverterUInt64.read(from: &buf), chatId: try FfiConverterString.read(from: &buf), message: try FfiConverterTypeMessageViewRecord.read(from: &buf)
        )
        
        case 8: return .stream(request: try FfiConverterUInt64.read(from: &buf), chatId: try FfiConverterString.read(from: &buf), event: try FfiConverterTypeStreamEventRecord.read(from: &buf)
        )
        
        case 9: return .status(message: try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .failed(error: try FfiConverterTypeViewErrorKindRecord.read(from: &buf)
        )
        
        case 11: return .done
        
        case 12: return .draftChanged(chatId: try FfiConverterString.read(from: &buf), draft: try FfiConverterOptionTypeDraftViewRecord.read(from: &buf)
        )
        
        case 13: return .unownedSocketFrame(eventType: try FfiConverterString.read(from: &buf), payloadJson: try FfiConverterString.read(from: &buf)
        )
        
        case 14: return .unownedSocketFramesDropped(count: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ViewEventRecord, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .session(event):
            writeInt(&buf, Int32(1))
            FfiConverterTypeSessionEventRecord.write(event, into: &buf)
            
        
        case let .syncProgress(phase,received):
            writeInt(&buf, Int32(2))
            FfiConverterTypeSyncPhaseRecord.write(phase, into: &buf)
            FfiConverterUInt64.write(received, into: &buf)
            
        
        case let .chatList(rows,completeness,totalCount):
            writeInt(&buf, Int32(3))
            FfiConverterSequenceTypeChatListRowRecord.write(rows, into: &buf)
            FfiConverterTypeListCompletenessRecord.write(completeness, into: &buf)
            FfiConverterOptionUInt64.write(totalCount, into: &buf)
            
        
        case let .chatWindow(request,window):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(request, into: &buf)
            FfiConverterTypeChatWindowViewRecord.write(window, into: &buf)
            
        
        case let .chatUnavailable(chatId):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(chatId, into: &buf)
            
        
        case let .chatOpenFailed(request,chatId,error):
            writeInt(&buf, Int32(6))
            FfiConverterUInt64.write(request, into: &buf)
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterTypeViewErrorKindRecord.write(error, into: &buf)
            
        
        case let .messageUpdated(request,chatId,message):
            writeInt(&buf, Int32(7))
            FfiConverterUInt64.write(request, into: &buf)
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterTypeMessageViewRecord.write(message, into: &buf)
            
        
        case let .stream(request,chatId,event):
            writeInt(&buf, Int32(8))
            FfiConverterUInt64.write(request, into: &buf)
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterTypeStreamEventRecord.write(event, into: &buf)
            
        
        case let .status(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .failed(error):
            writeInt(&buf, Int32(10))
            FfiConverterTypeViewErrorKindRecord.write(error, into: &buf)
            
        
        case .done:
            writeInt(&buf, Int32(11))
        
        
        case let .draftChanged(chatId,draft):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(chatId, into: &buf)
            FfiConverterOptionTypeDraftViewRecord.write(draft, into: &buf)
            
        
        case let .unownedSocketFrame(eventType,payloadJson):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(eventType, into: &buf)
            FfiConverterString.write(payloadJson, into: &buf)
            
        
        case let .unownedSocketFramesDropped(count):
            writeInt(&buf, Int32(14))
            FfiConverterUInt64.write(count, into: &buf)
            
        }
    }
}


